<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:50px}body{font-family:'DejaVu Sans',sans-serif;font-size:11px;color:#153d34;line-height:1.7}h1{font-size:28px;border-bottom:2px solid #153d34;padding-bottom:18px}table{width:100%;border-collapse:collapse;margin-top:20px}td{padding:12px;border-bottom:1px solid #dfe5dc}.muted{color:#68786f}.amount{font-size:22px;background:#e9eee2}</style></head><body><div class="muted">{{$invoice->company_snapshot['company_name']??'Sparkling Tours and Safaris'}}</div><h1>{{$payment->kind==='refund'?'REFUND ACKNOWLEDGEMENT':'PAYMENT RECEIPT'}}</h1><p>Receipt reference: REC-{{$payment->id}}<br>Invoice: {{$invoice->number}}<br>Booking: {{$invoice->booking->reference}}</p><table><tr><td>Customer</td><td>{{$invoice->customer_snapshot['name']}}</td></tr><tr><td>Date</td><td>{{$payment->paid_on->format('d M Y')}}</td></tr><tr><td>Transaction reference</td><td>{{$payment->transaction_reference}}</td></tr><tr><td>Payment method</td><td>{{$payment->method}}</td></tr><tr class="amount"><td>{{$payment->kind==='refund'?'Refund paid':'Verified amount received'}}</td><td>{{\App\Support\Money::format($payment->amount,$payment->currency)}}</td></tr><tr><td>Invoice remaining balance</td><td>{{\App\Support\Money::format($invoice->balanceMinor(),$invoice->currency)}}</td></tr></table><p class="muted">This acknowledgement reflects a verified ledger entry. Booking confirmation remains subject to the agreed supplier and payment arrangements.</p></body></html>
